import sys

def main():
    lines = sys.stdin.read().strip().split('\n')
    if not lines:
        return
    n = int(lines[0])
    operators = lines[1:n+1]

    typedefs = {}

    def resolve_type(type_str):
        base = ""
        stars = 0
        amps = 0

        i = 0
        while i < len(type_str):
            if type_str[i] == '*':
                stars += 1
                i += 1
            elif type_str[i] == '&':
                amps += 1
                i += 1
            else:
                break

        base = type_str[i:]

        if base == "void":
            depth = stars - amps
            if depth < 0:
                return "errtype"
            return "void" + "*" * depth
        elif base == "errtype":
            return "errtype"
        elif base in typedefs:
            resolved = resolve_type(typedefs[base])
            if resolved == "errtype":
                return "errtype"
            if resolved.startswith("void"):
                void_stars = len(resolved) - 4
                new_depth = void_stars + stars - amps
                if new_depth < 0:
                    return "errtype"
                return "void" + "*" * new_depth
            else:
                return "errtype"
        else:
            return "errtype"

    output_lines = []

    for op in operators:
        parts = op.split()
        if parts[0] == "typedef":
            A = parts[1]
            B = parts[2]
            resolved = resolve_type(A)
            typedefs[B] = resolved
        elif parts[0] == "typeof":
            A = parts[1]
            resolved = resolve_type(A)
            output_lines.append(resolved)

    for line in output_lines:
        print(line)

if __name__ == "__main__":
    main()
